{
  "claims": [
    {
      "claim_id": "c1",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that transaction IDs have limited size (32 bits).",
      "citations": [
        {
          "index": 0,
          "quote": "transaction IDs have limited size (32 bits)"
        }
      ]
    },
    {
      "claim_id": "c2",
      "verdict": "SUPPORTED",
      "reasoning": "The passage mentions 'more than 4 billion transactions' before wraparound, which corresponds to the 32-bit space of about 4 billion values.",
      "citations": [
        {
          "index": 0,
          "quote": "more than 4 billion transactions"
        }
      ]
    },
    {
      "claim_id": "c3",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that for every normal XID, there are two billion XIDs that are older and two billion that are newer.",
      "citations": [
        {
          "index": 1,
          "quote": "for every normal XID, there are two billion XIDs that are “older” and two billion that are “newer”"
        }
      ]
    },
    {
      "claim_id": "c4",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that it is necessary to vacuum every table in every database at least once every two billion transactions.",
      "citations": [
        {
          "index": 0,
          "quote": "it is necessary to vacuum every table in every database at least once every two billion transactions."
        }
      ]
    },
    {
      "claim_id": "c5",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says 'catastrophic data loss' but clarifies that the data is still there, just inaccessible, and that vacuuming can prevent it. It does not say it is permanent and unrecoverable.",
      "citations": [
        {
          "index": 0,
          "quote": "catastrophic data loss. (Actually the data is still there, but that's cold comfort if you cannot get at it.)"
        }
      ]
    },
    {
      "claim_id": "c6",
      "verdict": "SUPPORTED",
      "reasoning": "The default autovacuum_freeze_max_age is 200 million, which is 10% of 2 billion. The passage says autovacuum is invoked on tables with XIDs older than that age.",
      "citations": [
        {
          "index": 2,
          "quote": "autovacuum is invoked on any table that might contain unfrozen rows with XIDs older than the age specified by the configuration parameter autovacuum_freeze_max_age."
        },
        {
          "index": 5,
          "quote": "The default, 200 million transactions"
        }
      ]
    },
    {
      "claim_id": "c7",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states the effective maximum for vacuum_freeze_table_age is 0.95 * autovacuum_freeze_max_age. With default 200 million, that is 190 million, not 180 million. However, the claim says 'at most 180 million' which is incorrect; the maximum is 190 million. So the claim is contradicted.",
      "citations": [
        {
          "index": 4,
          "quote": "The effective maximum for vacuum_freeze_table_age is 0.95 * autovacuum_freeze_max_age"
        }
      ]
    },
    {
      "claim_id": "c8",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says warnings start at 40 million transactions from wraparound, and XID assignment stops at 3 million, so the difference is 37 million.",
      "citations": [
        {
          "index": 6,
          "quote": "when the database's oldest XIDs reach forty million transactions from the wraparound point"
        },
        {
          "index": 7,
          "quote": "the system will refuse to assign new XIDs once there are fewer than three million transactions left until wraparound"
        }
      ]
    },
    {
      "claim_id": "c9",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says only read-only transactions can be started, not that no new transactions of any kind can be started.",
      "citations": [
        {
          "index": 8,
          "quote": "only read-only transactions can be started"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "claim_id": "c1",
