    {
      "claim_id": "c3",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that autovacuum is invoked on tables with unfrozen rows older than autovacuum_freeze_max_age even if autovacuum is disabled.",
      "citations": [
        {
          "index": 0,
          "quote": "This will happen even if autovacuum is disabled."
