    {
      "claim_id": "c7",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that autovacuum processes table partitions just like other tables.",
      "citations": [
        {
          "index": 5,
          "quote": "Autovacuum does process table partitions just like other tables."
        }
      ]
    },
    {
      "claim_id": "c8",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that autovacuum does not run ANALYZE on partitioned tables.",
      "citations": [
        {
          "index": 5,
          "quote": "autovacuum does not run ANALYZE on partitioned tables"
        }
      ]
    },
    {
      "claim_id": "c9",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that the autovacuum daemon does not issue ANALYZE commands for foreign tables.",
      "citations": [
        {
          "index": 7,
          "quote": "The autovacuum daemon does not issue ANALYZE commands for foreign tables"
        }
      ]
    },
    {
      "claim_id": "c10",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says that if autovacuum is running to prevent wraparound, it is not automatically interrupted by conflicting lock requests.",
      "citations": [
        {
          "index": 6,
          "quote": "if the autovacuum is running to prevent transaction ID wraparound ... the autovacuum is not automatically interrupted."
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "claim_id": "c1",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that standard VACUUM can run in parallel with production database operations, including SELECT, INSERT, UPDATE, and DELETE.",
      "citations": [
        {
          "index": 0,
          "quote": "the standard form of VACUUM can run in parallel with production database operations. (Commands such as SELECT, INSERT, UPDATE, and DELETE will continue to function normally..."
        }
      ]
    },
    {
      "claim_id": "c2",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that VACUUM FULL requires an ACCESS EXCLUSIVE lock on the table it is working on.",
      "citations": [
        {
          "index": 0,
          "quote": "VACUUM FULL requires an ACCESS EXCLUSIVE lock on the table it is working on"
        }
      ]
    },
    {
      "claim_id": "c3",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage states that VACUUM FULL runs much more slowly than standard VACUUM, contradicting the claim that it is faster.",
      "citations": [
        {
          "index": 0,
          "quote": "VACUUM FULL can reclaim more disk space but runs much more slowly."
        }
      ]
    },
    {
      "claim_id": "c4",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says standard VACUUM does not return space to the operating system except in a special case, so it is not true that it never returns space.",
      "citations": [
        {
          "index": 2,
          "quote": "However, it will not return the space to the operating system, except in the special case where one or more pages at the end of a table become entirely free and an exclusive table lock can be easily obtained."
        }
      ]
    },
    {
      "claim_id": "c5",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that VACUUM FULL, CLUSTER, and table-rewriting ALTER TABLE temporarily use extra disk space approximately equal to the size of the table.",
      "citations": [
        {
          "index": 6,
          "quote": "Note that they also temporarily use extra disk space approximately equal to the size of the table, since the old copies of the table and indexes can't be released until the new ones are complete."
        }
      ]
    },
    {
      "claim_id": "c6",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that these operations temporarily use extra disk space approximately equal to the size of the table, so a 50 GB table would need about another 50 GB.",
      "citations": [
        {
          "index": 6,
          "quote": "they also temporarily use extra disk space approximately equal to the size of the table"
        }
      ]
    },
    {
      "claim_id": "c7",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that the autovacuum daemon will never issue VACUUM FULL, so any VACUUM FULL in the logs was not started by autovacuum.",
      "citations": [
        {
          "index": 3,
          "quote": "The autovacuum daemon attempts to work this way, and in fact will never issue VACUUM FULL."
        }
      ]
    },
    {
      "claim_id": "c8",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that TRUNCATE removes the entire content immediately without requiring a subsequent VACUUM or VACUUM FULL to reclaim disk space.",
      "citations": [
        {
          "index": 7,
          "quote": "TRUNCATE removes the entire content of the table immediately, without requiring a subsequent VACUUM or VACUUM FULL to reclaim the now-unused disk space."
        }
      ]
    },
    {
      "claim_id": "c9",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that the disadvantage of TRUNCATE is that strict MVCC semantics are violated.",
      "citations": [
        {
          "index": 7,
          "quote": "The disadvantage is that strict MVCC semantics are violated."
        }
      ]
    },
    {
      "claim_id": "c10",
      "verdict": "SUPPORTED",
      "reasoning": "The passage mentions that some installations with extremely high update rates vacuum their busiest tables as often as once every few minutes.",
      "citations": [
        {
          "index": 5,
          "quote": "Some installations with extremely high update rates vacuum their busiest tables as often as once every few minutes."
        }
      ]
    },
    {
      "claim_id": "c11",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passage says a typical approach is to schedule a database-wide VACUUM once a day, but it does not state that it is required.",
      "citations": []
    }
  ]
}

{
  "claims": [
    {
      "claim_id": "c1",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that before PostgreSQL 9.4, freezing was implemented by replacing a row's insertion XID with FrozenTransactionId.",
      "citations": [
        {
          "index": 0,
          "quote": "In PostgreSQL versions before 9.4, freezing was implemented by actually replacing a row's insertion XID with FrozenTransactionId"
        }
      ]
    },
    {
      "claim_id": "c2",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says that rows with xmin equal to FrozenTransactionId (2) may still be found in databases pg_upgrade'd from pre-9.4 versions, which includes 9.3. Thus, on a 9.3 cluster, frozen rows would have xmin of 2.",
      "citations": [
        {
          "index": 0,
          "quote": "rows with xmin equal to FrozenTransactionId (2) may still be found in databases pg_upgrade'd from pre-9.4 versions"
        }
      ]
    },
    {
      "claim_id": "c3",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passage mentions that newer versions use a flag bit and preserve the original xmin for possible forensic use, but it does not mention WAL volume as a reason.",
      "citations": []
